SET resolved_at = #{resolvedAt}, version = version + 1
WHERE workspace_id = #{workspaceId}
  AND family = #{family}
  AND resolved_at IS NULL
  AND generation_token <> #{generationToken}

UPDATE relationship_signal
SET resolved_at = #{resolvedAt}, version = version + 1
WHERE workspace_id = #{workspaceId}
  AND resolved_at IS NULL
  AND id IN
  #{id}

