mapper.update:
UPDATE relationship_signal_state
SET disposition = #{disposition},
    snooze_until = #{snoozeUntil},
    dismissed_source_hash = #{dismissedSourceHash},
    version = version + 1
WHERE workspace_id = #{workspaceId}
  AND signal_id = #{signalId}
  AND user_id = #{userId}
  AND version = #{expectedVersion}

UPDATE relationship_signal_state
SET task_id = #{taskId}, task_source_hash = #{sourceStateHash}, version = version + 1
WHERE workspace_id = #{workspaceId}
  AND signal_id = #{signalId}
  AND user_id = #{userId}
  AND version = #{expectedVersion}
  AND (
    task_id IS NULL
    OR task_source_hash IS NULL
    OR task_source_hash <> #{sourceStateHash}
    OR NOT EXISTS (
      SELECT 1 FROM task t
      WHERE t.workspace_id = #{workspaceId}
        AND t.id = relationship_signal_state.task_id
    )
  )

