  workspace_id, family, status, last_attempt_at, last_success_at, evidence_as_of, error_code
) VALUES (
  #{workspaceId}, #{family}, 'unavailable', #{attemptedAt}, NULL, NULL, 'not_generated'
)

INSERT INTO relationship_signal_family_state (
  workspace_id, family, status, last_attempt_at, last_success_at, evidence_as_of, error_code
) VALUES (
  #{workspaceId}, #{family}, 'unavailable', #{attemptedAt}, NULL, NULL, #{errorCode}
)
ON DUPLICATE KEY UPDATE
  status = 'unavailable', last_attempt_at = VALUES(last_attempt_at), error_code = VALUES(error_code)
